using System.Text.Json;

namespace Jellyfin.Plugin.GenreMapper.Genres;

/// <summary>
/// The official genres of the metadata providers, bundled with the plugin as they rarely change.
/// </summary>
/// <remarks>
/// <c>Data/tmdb-genres.json</c> is generated by <c>scripts/update_tmdb_genres.py</c>,
/// <c>Data/tvdb-genres.json</c> is copied from <see href="https://thetvdb.com/genres"/>.
/// </remarks>
public static class KnownGenres
{
    private const string DefaultLanguage = "en";

    private static readonly Lazy<TmdbFile> _tmdb = new(() => Read<TmdbFile>("tmdb-genres.json"));

    private static readonly Lazy<string[]> _tvdb = new(() => Read<string[]>("tvdb-genres.json"));

    /// <summary>
    /// Gets the official TheTVDB genres, only in English.
    /// </summary>
    public static IReadOnlyList<string> TvdbGenres => _tvdb.Value;

    /// <summary>
    /// Gets the official TMDb genres in a metadata language.
    /// </summary>
    /// <param name="type">The type of the items.</param>
    /// <param name="metadataLanguage">The metadata language, like <c>fr</c> or <c>pt-BR</c>.</param>
    /// <returns>The genres, in English if the language is unknown.</returns>
    public static IReadOnlyList<string> GetTmdbGenres(TmdbType type, string? metadataLanguage)
    {
        TmdbList list = type == TmdbType.Movie ? _tmdb.Value.Movie : _tmdb.Value.Tv;
        string code = (metadataLanguage ?? string.Empty).Trim();

        // Untranslated names are null, Jellyfin then gets them from the base language or in English
        string?[][] candidates = new[] { code, code.Split('-')[0], DefaultLanguage }
            .Select(language => list.Languages.FirstOrDefault(pair => string.Equals(pair.Key, language, StringComparison.OrdinalIgnoreCase)).Value)
            .OfType<string?[]>()
            .ToArray();

        return Enumerable.Range(0, list.Ids.Length)
            .Select(index => candidates.Select(names => names[index]).FirstOrDefault(name => name is not null))
            .OfType<string>()
            .ToArray();
    }

    private static T Read<T>(string name)
    {
        using Stream stream = typeof(KnownGenres).Assembly.GetManifestResourceStream(typeof(Plugin).Namespace + ".Data." + name)
            ?? throw new InvalidOperationException("Missing embedded resource " + name);
        return JsonSerializer.Deserialize<T>(stream, new JsonSerializerOptions { PropertyNameCaseInsensitive = true })
            ?? throw new InvalidOperationException("Invalid embedded resource " + name);
    }

    private sealed class TmdbFile
    {
        public TmdbList Movie { get; set; } = new();

        public TmdbList Tv { get; set; } = new();
    }

    private sealed class TmdbList
    {
        public int[] Ids { get; set; } = [];

        // The names of the genres in each language, in the order of the ids
        public Dictionary<string, string?[]> Languages { get; set; } = [];
    }
}

/// <summary>
/// The TMDb genre lists.
/// </summary>
public enum TmdbType
{
    /// <summary>
    /// The movie genres.
    /// </summary>
    Movie,

    /// <summary>
    /// The TV show genres.
    /// </summary>
    Tv
}
